// n8n Function node: Build Oakcent-style newsletter (ALL CONTENT CENTERED)
// Input: items[0].json = { meta, segments: [{ type, data }, ...] }
// Output: item.json.html (string) + item.binary.newsletter (HTML file)

// ---------- helpers ----------
const item = items[0];
const data = item.json || {};

const esc = (v = '') => String(v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const aIf = (cond, html) => cond ? html : '';
const space = (h=12) => `<div style="line-height:0; height:${h}px; font-size:0;">&nbsp;</div>`;
const dividerH = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center"><tr><td style="border-top:1px solid #cdc5bf; height:1px; line-height:1px; font-size:0;"></td></tr></table>`;
const btnOutline = (href, text) =>
  `<a href="${esc(href)}" style="display:inline-block; padding:12px 18px; border:1px solid #3b3b3b; color:#3b3b3b; text-decoration:none; border-radius:4px; font-family:Arial, sans-serif;">${esc(text)}</a>`;
const btnSolidWhite = (href, text) =>
  `<a href="${esc(href)}" style="display:inline-block; padding:12px 18px; background:#ffffff; color:#111827; text-decoration:none; border-radius:2px; font-family:Arial, sans-serif; font-weight:bold;">${esc(text)}</a>`;

// brand palette (inline for email)
const BG = '#e9dfd7';        // light beige page background
const TEXT = '#3b3b3b';      // primary text
const MUTED = '#6b6b6b';     // secondary text
const DARK = '#232323';      // dark block background

// ---------- layout ----------
const layoutStart = (meta = {}) => `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="x-apple-disable-message-reformatting">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(meta.subject || '')}</title>
</head>
<body style="margin:0; padding:0; background:${BG};">
  <div style="display:none; visibility:hidden; opacity:0; color:transparent; height:0; width:0; overflow:hidden;">
    ${esc(meta.preheader || '')}
  </div>
  <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:${BG};">
    <tr>
      <td align="center">
        <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="width:600px; max-width:100%;">
          <tr><td align="center" style="padding:20px; font-family:Arial, sans-serif; color:${TEXT}; font-size:16px; line-height:1.5; text-align:center;">`;

const layoutEnd = `</td></tr></table></td></tr></table></body></html>`;

// ---------- segments ----------

// 1) HERO / INTRO (centered logo, hero, two columns centered)
function segment_intro(d = {}) {
  const right = (d.right_images || []).slice(0,2);
  return `
  ${aIf(d.logo_url, `
    <div style="text-align:center;">${aIf(d.logo_url, `<img src="${esc(d.logo_url)}" alt="${esc(d.logo_alt || 'Logo')}" width="120" style="display:inline-block; border:0; margin:0 auto;">`)}</div>
    ${space(12)}`)}
  ${aIf(d.hero_image_url, `
    <img src="${esc(d.hero_image_url)}" alt="${esc(d.hero_image_alt || '')}" width="560" style="display:block; width:100%; max-width:560px; border:0; margin:0 auto;">
    ${space(16)}`)}

  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center">
    <tr>
      <td valign="top" width="66%" align="center" style="padding-right:16px; text-align:center;">
        ${aIf(d.kicker, `<div style="text-transform:uppercase; letter-spacing:.04em; font-size:12px; color:${MUTED};">${esc(d.kicker)}</div>`)}
        ${aIf(d.title, `<h1 style="margin:6px 0 10px; color:${TEXT}; font-size:24px;">${esc(d.title)}</h1>`)}
        ${aIf(d.body_html, `<div style="text-align:center;">${d.body_html}</div>`)}
        ${space(12)}
        ${aIf(d.cta_url, btnOutline(d.cta_url, d.cta_text || 'Zjistit více'))}
      </td>
      <td valign="top" width="34%" align="center" style="text-align:center;">
        ${right.map((u,i) => `
          ${i ? space(12) : ''}<img src="${esc(u.url)}" alt="${esc(u.alt || '')}" width="180" style="display:block; width:100%; max-width:180px; border:0; margin:0 auto;">
        `).join('')}
      </td>
    </tr>
  </table>`;
}

// 2) PROJECT STORY (centered)
function segment_project_story(d = {}) {
  const left = (d.left_images || []).slice(0,2);
  return `
  ${aIf(d.top_image_url, `
    <img src="${esc(d.top_image_url)}" alt="${esc(d.top_image_alt || '')}" width="560" style="display:block; width:100%; max-width:560px; border:0; margin:0 auto;">
    ${space(16)}`)}

  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center">
    <tr>
      <td valign="top" width="40%" align="center" style="padding-right:16px; text-align:center;">
        ${left.map((u,i) => `
          ${i ? space(12) : ''}<img src="${esc(u.url)}" alt="${esc(u.alt || '')}" width="220" style="display:block; width:100%; max-width:220px; border:0; margin:0 auto;">
        `).join('')}
      </td>
      <td valign="top" width="60%" align="center" style="text-align:center;">
        ${aIf(d.title, `<h2 style="margin:0 0 8px; color:${TEXT}; font-size:22px;">${esc(d.title)}</h2>`)}
        ${aIf(d.body_html, `<div style="text-align:center;">${d.body_html}</div>`)}
        ${space(12)}
        ${aIf(d.cta_url, btnOutline(d.cta_url, d.cta_text || 'Prohlédněte si projekt'))}
      </td>
    </tr>
  </table>`;
}

// 3 & 4) COLLECTION / PATTERN rows (centered text; keeps left divider)
function swatchRow(r = {}) {
  return `
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" align="center">
    <tr>
      <td valign="top" width="120" align="center" style="padding-right:16px; text-align:center;">
        ${aIf(r.swatch_url, `<img src="${esc(r.swatch_url)}" alt="${esc(r.swatch_alt || '')}" width="100" style="display:block; width:100px; height:100px; border-radius:50%; border:0; margin:0 auto;">`)}
      </td>
      <td valign="top" align="center" style="border-left:1px solid #cdc5bf; padding-left:16px; text-align:center;">
        ${aIf(r.label, `<div style="font-size:12px; color:${MUTED}; text-transform:uppercase; letter-spacing:.02em;">${esc(r.label)}</div>`)}
        ${aIf(r.name, `<div style="font-size:20px; margin:6px 0 6px; color:${TEXT};"><strong>${esc(r.name)}</strong></div>`)}
        ${aIf(r.desc_html, `<div style="text-align:center;">${r.desc_html}</div>`)}
        ${space(10)}
        ${aIf(r.cta_url, btnOutline(r.cta_url, r.cta_text || 'Zjistit více'))}
      </td>
    </tr>
  </table>`;
}
function segment_collection_and_pattern(d = {}) {
  const top = swatchRow(d.collection || {});
  const bottom = swatchRow(d.pattern || {});
  return `${top}${space(12)}${dividerH}${space(12)}${bottom}`;
}

// 5) FULL-WIDTH IMAGE (centered)
function segment_full_width_image(d = {}) {
  return `
  <img src="${esc(d.image_url)}" alt="${esc(d.alt || '')}" width="560" style="display:block; width:100%; max-width:560px; border:0; margin:0 auto;">`;
}

// 6) DARK CTA (already centered)
function segment_dark_cta(d = {}) {
  const socials = (d.socials || []).slice(0,8);
  return `
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${DARK}; border-radius:2px;" align="center">
    <tr><td align="center" style="padding:28px 16px; text-align:center;">
      ${aIf(d.title, `<div style="font-family:Arial, sans-serif; color:#ffffff; font-size:22px; font-weight:bold; margin:0 0 10px;">${esc(d.title)}</div>`)}
      ${aIf(d.subtitle, `<div style="font-family:Arial, sans-serif; color:#e5e5e5; margin:0 0 14px;">${esc(d.subtitle)}</div>`)}
      ${aIf(d.cta_url, btnSolidWhite(d.cta_url, d.cta_text || 'OPEN'))}
      ${aIf(socials.length, `
        ${space(16)}
        <table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center">
          <tr>
            ${socials.map(s => `
              <td style="padding:0 6px;">
                <a href="${esc(s.url)}"><img src="${esc(s.icon_url)}" alt="${esc(s.alt || '')}" width="20" style="display:block; border:0; margin:0 auto;"></a>
              </td>
            `).join('')}
          </tr>
        </table>`)}
    </td></tr>
  </table>`;
}

// map of segment types
const renderers = {
  segment_intro,
  segment_project_story,
  segment_collection_and_pattern,
  segment_full_width_image,
  segment_dark_cta,
};

// ---------- build body ----------
let body = '';
const list = Array.isArray(data.segments) ? data.segments : [];
for (let i = 0; i < list.length; i++) {
  const seg = list[i] || {};
  const fn = renderers[seg.type];
  if (fn) {
    body += fn(seg.data || {});
  } else {
    body += `<!-- Missing renderer for ${esc(seg.type)} -->`;
  }
  if (i < list.length - 1) body += space(18);
}

// ---------- finalize ----------
const html = layoutStart(data.meta || {}) + body + layoutEnd;

item.json.html = html;
item.binary = item.binary || {};
item.binary.newsletter = {
  data: Buffer.from(html, 'utf8').toString('base64'),
  fileName: 'newsletter.html',
  mimeType: 'text/html',
};

return items;

// n8n Function node
// Expects your big JSON object (with template_html, blog_*, project_*, etc.) on item.json
// Outputs the same JSON + html_rendered (final email HTML)

return items.map(item => {
  const data = item.json;

  const base = (data.image_base_url || '').replace(/\/$/, '');

  const t = (v) => (typeof v === 'string' ? v.trim() : (v ?? ''));
  const full = (v) => {
    const s = t(v);
    if (!s) return '';
    if (/^https?:\/\//i.test(s)) return s; // already absolute
    return base + s;
  };

  // NEW: Supabase bases for collection & pattern images
  const supabaseCollectionBase = 'https://izohjxqvhacjmutgnckf.supabase.co/storage/v1/object/public/Newsletter/collection_images/';
  const supabasePatternBase   = 'https://izohjxqvhacjmutgnckf.supabase.co/storage/v1/object/public/Newsletter/pattern_images/';

  // Helper: build Supabase image URL from name, if provided
  const supabaseImg = (baseUrl, nameRaw) => {
    const name = t(nameRaw);
    if (!name) return '';
    // We assume filenames are exactly "<name>.png"
    return `${baseUrl}${name}.png`;
  };

  let html = t(data.template_html);
  if (!html) {
    throw new Error('template_html is missing on item.json');
  }

  // ✅ UPDATED: whitespace-tolerant replacement for [[TOKEN]]
  // Works with: [[TOKEN]], [[ TOKEN ]],  [[TOKEN]], url(' [[TOKEN]]'), href=" [[TOKEN]]"
  const rep = (tokenRaw, value) => {
    const val = (value ?? '').toString();

    // Accept calls like rep('[[EMAIL_TITLE]]', ...) OR rep('EMAIL_TITLE', ...)
    const token = String(tokenRaw)
      .replace(/^\[\[\s*/, '')
      .replace(/\s*\]\]$/, '')
      .trim();

    // Escape token for RegExp
    const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // Match [[TOKEN]] with any whitespace around TOKEN
    const re = new RegExp(`\\[\\[\\s*${escaped}\\s*\\]\\]`, 'g');

    html = html.replace(re, val);
  };

  //
  // 1) Global / fonts / logo / background structures
  //
  rep('[[EMAIL_TITLE]]', t(data.blog_title));

  rep('[[FONT_CASLONDORIC_URL]]', t(data.font_1));
  rep('[[FONT_ROMNARROW_URL]]', t(data.font_2));

  rep('[[STRUCTURE_BACKGROUND_IMAGE_1]]', full(data.structure_1));
  rep('[[STRUCTURE_BACKGROUND_IMAGE_2]]', full(data.structure_2));

  rep('[[LOGO_SRC]]', t(data.logo_src));
  rep('[[LOGO_ALT]]', t(data.logo_alt) || 'OAKCENT');

  //
  // 2) Magazine (blog) block
  //
  rep('[[HERO_IMAGE_1_SRC]]', full(data.heroImgBlog));
  rep('[[HERO_IMAGE_1_ALT]]', t(data.blog_title));

  rep('[[MAGAZINE_SIDE_IMAGE_1_SRC]]', full(data.sideImgBlog_1));
  rep('[[MAGAZINE_SIDE_IMAGE_1_ALT]]', t(data.blog_title));

  rep('[[MAGAZINE_SIDE_IMAGE_2_SRC]]', full(data.sideImgBlog_2));
  rep('[[MAGAZINE_SIDE_IMAGE_2_ALT]]', t(data.blog_title));

  rep('[[GALLERY_IMAGE_1_SRC]]', full(data.galleryImgBlog));
  rep('[[GALLERY_IMAGE_1_ALT]]', t(data.blog_title));

  rep('[[MAGAZINE_LABEL]]', 'Magazine');
  rep('[[MAGAZINE_TITLE]]', t(data.blog_title));

  const blogText =
    t(data.blog_text) ||
    [data.blog_p1, data.blog_p2, data.blog_p3, data.blog_p4, data.blog_p5, data.blog_p6]
      .map(t)
      .filter(Boolean)
      .join(' ');

  rep('[[MAGAZINE_TEXT]]', blogText);

  rep('[[MAGAZINE_PARAGRAPH_1]]', '');
  rep('[[MAGAZINE_PARAGRAPH_2]]', '');
  rep('[[MAGAZINE_PARAGRAPH_3]]', '');
  rep('[[MAGAZINE_PARAGRAPH_4]]', '');
  rep('[[MAGAZINE_PARAGRAPH_5]]', '');
  rep('[[MAGAZINE_PARAGRAPH_6]]', '');

  rep('[[MAGAZINE_CTA_LABEL]]', t(data.blog_cta_label));

  const blogUrl = t(data.blog_url) || full('/magazine/custom-production');
  rep('[[MAGAZINE_CTA_URL]]', blogUrl);

  //
  // 3) Project block
  //
  rep('[[PROJECT_HERO_IMAGE_SRC]]', full(data.heroImgProject));
  rep('[[PROJECT_HERO_IMAGE_ALT]]', t(data.project_title));

  rep('[[PROJECT_IMAGE_1_SRC]]', full(data.firstBlock_img));
  rep('[[PROJECT_IMAGE_1_ALT]]', t(data.project_title));

  rep('[[PROJECT_IMAGE_2_SRC]]', full(data.secondBlock_img));
  rep('[[PROJECT_IMAGE_2_ALT]]', t(data.project_title));

  rep('[[PROJECT_TITLE]]', t(data.project_title));

  const projectText =
    t(data.project_text) ||
    [data.project_p1, data.project_p2, data.project_p3, data.project_p4, data.project_p5]
      .map(t)
      .filter(Boolean)
      .join(' ');

  rep('[[PROJECT_TEXT]]', projectText);

  rep('[[PROJECT_PARAGRAPH_1]]', '');
  rep('[[PROJECT_PARAGRAPH_2]]', '');
  rep('[[PROJECT_PARAGRAPH_3]]', '');
  rep('[[PROJECT_PARAGRAPH_4]]', '');
  rep('[[PROJECT_PARAGRAPH_5]]', '');

  rep('[[PROJECT_CTA_LABEL]]', t(data.project_cta_label));

  const projectUrl = t(data.project_url) || full('/projects');
  rep('[[PROJECT_CTA_URL]]', projectUrl);

  //
  // 4) Collection block
  //
  rep('[[COLLECTION_LABEL]]', 'Colour Collection');
  rep('[[COLLECTION_TITLE]]', t(data.collection_title));

  const collectionImageName = data.collection_name || data.collection_title;
  const collectionSupabaseSrc = supabaseImg(supabaseCollectionBase, collectionImageName);
  const collectionImageSrcFinal = collectionSupabaseSrc || full(data.collection_image);

  rep('[[COLLECTION_IMAGE_SRC]]', collectionImageSrcFinal);
  rep('[[COLLECTION_IMAGE_ALT]]', t(data.collection_title));

  const collectionText =
    t(data.collection_body) ||
    [data.collection_paragraph_1, data.collection_paragraph_2, data.collection_paragraph_3]
      .map(t)
      .filter(Boolean)
      .join(' ');

  rep('[[COLLECTION_TEXT]]', collectionText);

  rep('[[COLLECTION_PARAGRAPH_1]]', '');
  rep('[[COLLECTION_PARAGRAPH_2]]', '');
  rep('[[COLLECTION_PARAGRAPH_3]]', '');

  rep('[[COLLECTION_CTA_LABEL]]', t(data.collection_cta));

  const collectionUrl = t(data.collection_url) || '/floor-collection/sand';
  rep('[[COLLECTION_CTA_URL]]', full(collectionUrl));

  //
  // 5) Pattern block
  //
  rep('[[PATTERN_LABEL]]', 'Pattern Collection');
  rep('[[PATTERN_TITLE]]', t(data.pattern_title));

  const patternImageName = data.pattern_name || data.pattern_title;
  const patternSupabaseSrc = supabaseImg(supabasePatternBase, patternImageName);
  const patternImageSrcFinal = patternSupabaseSrc || full(data.pattern_img1);

  rep('[[PATTERN_IMAGE_SRC]]', patternImageSrcFinal);
  rep('[[PATTERN_IMAGE_ALT]]', t(data.pattern_collectionName) || t(data.pattern_title));

  const patternText =
    t(data.pattern_text) ||
    [data.pattern_body, data.pattern_paragraph_2]
      .map(t)
      .filter(Boolean)
      .join(' ');

  rep('[[PATTERN_TEXT]]', patternText);

  rep('[[PATTERN_PARAGRAPH_1]]', '');
  rep('[[PATTERN_PARAGRAPH_2]]', '');

  rep('[[PATTERN_CTA_LABEL]]', t(data.pattern_cta));

  const patternUrl = t(data.pattern_collectionUrl) || '/floor-collection/heritage';
  rep('[[PATTERN_CTA_URL]]', full(patternUrl));

  //
  // 6) CTA over forest background
  //
  rep('[[CTA_BACKGROUND_IMAGE]]', full(data.cta_background));
  rep('[[CTA_HEADLINE]]', t(data.ctaContent));
  rep('[[CTA_BUTTON_LABEL]]', t(data.ctaButton));

  const ctaButtonUrl = t(data.cta_button_url) || '#';
  rep('[[CTA_BUTTON_URL]]', ctaButtonUrl);

  //
  // 7) Socials
  //
  rep('[[SOCIAL_WEB_URL]]', t(data.soc_web_url) || '#');
  rep('[[SOCIAL_WEB_ICON_SRC]]', full(data.soc_web_src));
  rep('[[SOCIAL_WEB_ICON_ALT]]', t(data.soc_web_alt) || 'web');

  rep('[[SOCIAL_INSTAGRAM_URL]]', t(data.soc_ig_url) || '#');
  rep('[[SOCIAL_INSTAGRAM_ICON_SRC]]', full(data.soc_ig_src));
